--region init
function CommonActivityBossRankRewardDialog:InitHandler()
	SetButtonAction(self.BtnClose, Bind(self, self.OnCloseHandler))
	SetButtonAction(self.Fuzzy, Bind(self, self.OnCloseHandler))
end

function CommonActivityBossRankRewardDialog:InitData()
	---@type Engine.UI.UIArgument
	local argument = self.controller.Argument
	local t = checkTable(argument.parameters)
	local entryCtrl = t.entryMgr
	if isNotNull(entryCtrl) then
		if checkInt(t.rankType) == 1 then
			self._rewardsList =  entryCtrl:GetBossRankRewardVos() --CfUtils.GetCf(AutoIds.IdSetting6455, "ActivityCakeBossRankVo", true)
		else
			self._rewardsList = entryCtrl:GetSplitRankRewardsVos()  --CfUtils.GetCf(AutoIds.IdSetting6466, "ActivityCakeBossRankVo", true)
		end
		self:RefreshUI()
	end
end
--endregion init

--region handler
function CommonActivityBossRankRewardDialog:OnCloseHandler()
	UIModule.CloseDialog(self.controller)
end
--endregion handler

--region private
function CommonActivityBossRankRewardDialog:FillItemByIndex(loopView, index)
	local luaIndex = index + 1
	local cellData = self._rewardsList[luaIndex]
	local cell = loopView:NewListViewItem("Cell")
	---@type UIActivityMidFestivalBossRankRewardCell
	local scr = CfUtils.GetLuaScr(cell, "Game.Behaviours.CommonActivityBossRankCell")
	scr:Refresh(cellData)
	return cell
end

function CommonActivityBossRankRewardDialog:RefreshUI()
	if not self.RankingLoopView.IsListViewInit then
		self.RankingLoopView:InitListView(#self._rewardsList, Bind(self, self.FillItemByIndex))
	else
		GameUtils.ReloadData(self.RankingLoopView, #self._rewardsList)
	end
end
--endregion private

